import sailpoint.messagebus.monitoring.api.ActiveMQDestinationView;
import sailpoint.messagebus.monitoring.api.ActiveMQMonitoringView;
import sailpoint.messagebus.monitoring.impl.ActiveMQMonitoringServiceImpl;

String QUEUE_NAME = "queue://treysDumpingGround";

long size = -1;
ActiveMQMonitoringView view = ActiveMQMonitoringServiceImpl.getInstance().getMonitoringView(context);
List queues = view.getQueues();

for (ActiveMQDestinationView destView : queues) {
    if (QUEUE_NAME.equals(destView.getDestinationName())) {
        size = destView.getQueueSize();
    }
}

return size;
